    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    def objective(x):
        return func(x)

    n = 20
    population_size = 100

    initial_population = generate_initial_population(n, dim, lb, ub)
    current_best = np.inf
    best_solution = None

    for i in range(budget):
        # CMA-ES step
